# Lesson content. ('show', code, stdin) outputs are computed by real CPython at build time.
LESSONS = []
def L(n, title, emoji, minutes, goal, cando, blocks):
    LESSONS.append(dict(n=n, title=title, emoji=emoji, minutes=minutes, goal=goal, cando=cando, blocks=blocks))

L(1, 'print() - make the computer talk', '💬', 20,
  'Know exactly what print shows for text, numbers, commas and +.',
  ['I put text in quotes', 'I know print("5 + 5") and print(5 + 5) are different', 'I know a comma adds a space and + does not', 'I can spot a missing quote or bracket'],
  [
  ('p', '<code>print()</code> shows something on the screen. Whatever you put inside the brackets is what appears.'),
  ('try', 'print("Hello, world!")', [], 'Press <b>Run</b>. Then change the words and run again.'),
  ('rule', 'Rule 1: text needs quotes', 'Anything in <b>quotes</b> is <b>text</b> (Python calls it a <b>str</b>). Python prints the text exactly as written. <b>The quotes are not printed.</b>'),
  ('show', 'print("Hello")\nprint(\'Hello\')', []),
  ('p', 'Double quotes <code>" "</code> and single quotes <code>\' \'</code> both work. Just close with the same kind you opened with.'),
  ('rule', 'Rule 2: numbers have NO quotes', 'A number without quotes is a number, so Python can do <b>math</b> with it. With quotes it is just text.'),
  ('show', 'print(2 + 3)\nprint("2 + 3")', []),
  ('trap', '<b>The classic trap:</b> <code>print("2 + 3")</code> prints <code>2 + 3</code>. <code>print(2 + 3)</code> prints <code>5</code>. Quotes = no math.'),
  ('quick', 'What does print("10 - 4") show?', ['10 - 4', '6', 'Error', '"10 - 4"'], 0, 'It is in quotes, so it is text and is printed as is.'),
  ('h', 'Putting several things in one print'),
  ('p', 'Put a <b>comma</b> between things. Python prints them with <b>one space</b> between. You can mix text and numbers.'),
  ('show', 'print("I am", 11, "years old")\nprint("Score:", 5 + 5)', []),
  ('p', 'Or use <b>+</b> to <b>glue text to text</b>. + adds <b>no space</b> - you have to put the space in the quotes yourself.'),
  ('show', 'print("Good" + "bye")\nprint("Good " + "morning")\nprint("5" + "5")', []),
  ('trap', '<b>+ with two numbers adds. + with two texts glues.</b> <code>5 + 5</code> is 10, but <code>"5" + "5"</code> is 55. And <b>text + number is an ERROR</b>: <code>print("Age: " + 11)</code> crashes. Use a comma instead: <code>print("Age:", 11)</code>.'),
  ('try', 'print("Age:", 11)\nprint("Age: " + 11)', [], 'Run it. The first line works, the second crashes. Read the red error message!'),
  ('h', 'Many lines'),
  ('p', 'Every <code>print()</code> starts a <b>new line</b>. Python reads your program from the top to the bottom.'),
  ('show', 'print("line one")\nprint("line two")\nprint()\nprint("after a blank line")', []),
  ('h', 'Mistakes that break print'),
  ('table', ['Mistake', 'What happens'], [
     ['<code>print("Hello)</code> (missing closing quote)', 'SyntaxError'],
     ['<code>print("Hello"</code> (missing closing bracket)', 'SyntaxError'],
     ['<code>Print("Hello")</code> (capital P)', 'NameError'],
     ['<code>print(Hello)</code> (no quotes)', 'NameError - Python thinks Hello is a variable'],
     ['<code>print "Hello"</code> (no brackets)', 'SyntaxError'],
     ['<code>print("a" "b")</code> (no comma or +)', 'Prints ab - stuck together']]),
  ('quick', 'Which line prints the word Python with a SPACE and then the number 3?', ['print("Python", 3)', 'print("Python" + 3)', 'print("Python"3)', 'print(Python, 3)'], 0, 'Comma = a space, and it allows text AND numbers.'),
  ])

L(2, 'Variables & math', '📦', 25,
  'Store values in names, update them, and predict the result of math.',
  ['I know x = 5 stores the value 5 in x', 'I know print(x) and print("x") are different', 'I can follow x = x + 1', 'I know / always gives a float'],
  [
  ('p', 'A <b>variable</b> is a <b>name tag on a box</b> that holds a value. You make one with the equals sign.'),
  ('try', 'score = 10\nprint(score)', [], 'Press <b>Step</b> (the ▶ button) to go one line at a time and watch the variable box appear on the right.'),
  ('rule', 'One = means STORE', '<code>x = 5</code> reads as "<b>put 5 into x</b>". It is NOT a question. Python always works <b>right side first</b>, then stores the answer in the name on the left.'),
  ('p', 'Once a variable exists you can use its name anywhere - <b>without quotes</b>.'),
  ('show', 'a = 3\nb = 4\nprint(a + b)\nprint(a * b)', []),
  ('trap', '<b>Name vs text:</b> <code>print(score)</code> shows what is INSIDE the box. <code>print("score")</code> prints the word score. Quotes turn a variable name back into plain text.'),
  ('show', 'name = "Ana"\nprint(name)\nprint("name")', []),
  ('h', 'Changing a variable'),
  ('p', 'A new value <b>replaces</b> the old one. Read <code>x = x + 1</code> as: "take the old x, add 1, store it back in x".'),
  ('try', 'x = 4\nx = x + 1\nprint(x)\nx = x * 3\nprint(x)', [], 'Step through it and watch x change.'),
  ('trap', '<code>x + 5</code> by itself calculates and <b>throws the answer away</b>. To keep it you must store it: <code>x = x + 5</code>.'),
  ('h', 'Variable names'),
  ('table', ['Allowed', 'NOT allowed'], [['<code>score</code>, <code>my_age</code>, <code>total2</code>', '<code>my age</code> (space), <code>2cool</code> (starts with a number), <code>my-age</code> (dash)'],
                                         ['Capital letters count: <code>Score</code> and <code>score</code> are two different names', '']]),
  ('h', 'Math'),
  ('table', ['Symbol', 'Meaning', 'Example', 'Result'], [['<code>+</code>', 'add', '<code>7 + 2</code>', '9'], ['<code>-</code>', 'subtract', '<code>7 - 2</code>', '5'],
      ['<code>*</code>', 'multiply', '<code>7 * 2</code>', '14'], ['<code>/</code>', 'divide', '<code>7 / 2</code>', '3.5']]),
  ('rule', '/ ALWAYS gives a float', 'Dividing with <code>/</code> always gives a number with a decimal point - <b>even when it divides evenly</b>: <code>10 / 2</code> is <code>5.0</code>, not 5.'),
  ('show', 'print(10 / 2)\nprint(7 / 2)\nprint(3 * 4)\nprint(3 * 4.0)', []),
  ('rule', 'Order of operations (like math class)', 'Brackets first, then <code>*</code> and <code>/</code>, then <code>+</code> and <code>-</code>.'),
  ('show', 'print(2 + 3 * 4)\nprint((2 + 3) * 4)\nprint(10 - 2 * 3)', []),
  ('quick', 'x = 3 then x = x + 2. What is x now?', ['5', '3', '2', '32'], 0, 'Old x is 3, add 2, store 5.'),
  ('quick', 'What does print(8 / 4) show?', ['2.0', '2', '4', 'Error'], 0, 'Division with / always gives a float.'),
  ])

L(3, 'input() - ask the user', '⌨️', 20,
  'Use input() and know that it ALWAYS gives text.',
  ['I use input() and store the answer in a variable', 'I know input() always gives text, even if the user types digits', 'I know "3" + "4" is "34"', 'I know text * number repeats'],
  [
  ('p', '<code>input()</code> pauses the program, waits for the user to type and press Enter, and gives you back what they typed. <b>Store it in a variable</b> or it is lost.'),
  ('try', 'name = input("What is your name? ")\nprint("Hello", name)', ['Sam'], 'Run it and type a name in the box that appears below.'),
  ('p', 'The words inside the brackets are the <b>prompt</b> - just a message for the user. It is <b>not</b> part of the answer.'),
  ('rule', 'THE most important rule of the whole test', '<b>input() ALWAYS gives you text (a str).</b> Even if the user types <code>7</code>, you get the <b>text</b> <code>"7"</code>, not the number 7. Python never guesses.'),
  ('p', 'That is why this program glues instead of adding:'),
  ('show', 'a = input()\nb = input()\nprint(a + b)', ['3', '4']),
  ('p', '<code>"3" + "4"</code> is text + text, so it <b>glues</b> to <code>34</code>. The same happens with *:'),
  ('show', 'n = input()\nprint(n * 3)', ['5']),
  ('trap', 'Text <b>cannot do math with numbers</b>. This crashes with a TypeError:'),
  ('try', 'n = input()\nprint(n + 1)', ['5'], 'Run it - read the error. Next lesson fixes it with <code>int()</code>.'),
  ('quick', 'The user types 8 into x = input(). What is x?', ['The text "8"', 'The number 8', 'The float 8.0', 'Nothing'], 0, 'input() = text, always.'),
  ('quick', 'a = input() and b = input() with 2 then 5. What does print(a + b) show?', ['25', '7', '10', 'Error'], 0, 'Text glued: 25.'),
  ])

L(4, 'int() and float() - turn text into numbers', '🔢', 30,
  'Convert input to numbers and choose int vs float correctly.',
  ['I write int(input()) for whole numbers', 'I write float(input()) for decimals', 'I know int(7.9) is 7 (chops)', 'I know float always shows .0'],
  [
  ('p', 'To do math with what the user typed, <b>convert</b> the text into a number first.'),
  ('table', ['Function', 'Does', 'Example', 'Result'], [
     ['<code>int(...)</code>', 'makes a <b>whole</b> number', '<code>int("5")</code>', '5'],
     ['<code>float(...)</code>', 'makes a number <b>with a decimal point</b>', '<code>float("5")</code>', '5.0'],
     ['<code>int(7.9)</code>', 'chops off the decimals (does NOT round)', '<code>int(7.9)</code>', '7']]),
  ('try', 'age = int(input("Age: "))\nprint("Next year you will be", age + 1)', ['11'], 'Type a whole number. Now the + really adds.'),
  ('rule', 'The 3-step pattern', '<code>x = int(input("..."))</code> &nbsp;or&nbsp; <code>x = float(input("..."))</code><br>Read it from the inside: <b>input</b> gets the text, <b>int/float</b> converts it, <b>x =</b> stores it.'),
  ('h', 'int or float?'),
  ('table', ['Use', 'When', 'Example answers'], [['<code>int(input())</code>', 'whole numbers (counting)', 'age, how many apples, a score'],
     ['<code>float(input())</code>', 'might have a decimal point', 'price, height, temperature, a measurement']]),
  ('show', 'a = float(input())\nprint(a * 2)', ['4']),
  ('trap', 'A float <b>always prints with a decimal point</b>: <code>4</code> doubled is <code>8.0</code>, not 8. And <code>10 / 2</code> is <code>5.0</code>. If the test asks for a whole number answer, you probably need <code>int</code>.'),
  ('h', 'int() chops, it does not round'),
  ('show', 'print(int(7.9))\nprint(int(7.1))\nprint(int(-7.9))\nprint(int(3.0))', []),
  ('h', 'When conversion crashes'),
  ('table', ['Code', 'Result', 'Why'], [
     ['<code>int("3.5")</code>', 'ValueError', 'int() only understands whole-number text'],
     ['<code>int("five")</code>', 'ValueError', 'not digits'],
     ['<code>float("abc")</code>', 'ValueError', 'not a number'],
     ['<code>int("")</code>', 'ValueError', 'empty text'],
     ['<code>float("3")</code>', '3.0', 'works']]),
  ('try', 'x = int(input("A whole number: "))\nprint(x * 2)', ['3.5'], 'The user typed 3.5! Read the error, then change <code>int</code> to <code>float</code> and try again.'),
  ('h', 'Mixing int and float'),
  ('p', 'Any math that includes a float gives a float. int + int stays int (except <code>/</code>).'),
  ('show', 'print(2 + 3)\nprint(2 + 3.0)\nprint(2 * 3)\nprint(6 / 3)\nprint(6 / 3.0)', []),
  ('quick', 'What does print(int("12") + int("8")) show?', ['20', '128', '12 + 8', 'Error'], 0, 'Both converted to numbers, then added.'),
  ('quick', 'What does int(9.99) give?', ['9', '10', '9.99', '9.0'], 0, 'int() chops.'),
  ('quick', 'The user types 2.5. Which line does NOT crash?', ['x = float(input())', 'x = int(input())', 'Both crash', 'x = int("2.5")'], 0, 'int() cannot read text with a decimal point.'),
  ])

L(5, 'Types & errors - the trap lesson', '🪤', 25,
  'Predict the type of anything and read the 4 error names.',
  ['I know str, int, float', 'I can say if an expression gives int, float, str or error', 'I know TypeError vs ValueError vs NameError vs SyntaxError', 'I can find which line crashes'],
  [
  ('p', 'Every value has a <b>type</b>. There are three you need:'),
  ('table', ['Type', 'What it is', 'Looks like'], [['<b>int</b>', 'whole number', '<code>5</code>, <code>-3</code>, <code>100</code>'], ['<b>float</b>', 'number with a decimal point', '<code>5.0</code>, <code>2.5</code>, <code>-0.5</code>'],
     ['<b>str</b>', 'text - anything in quotes', '<code>"5"</code>, <code>"hello"</code>, <code>"2.5"</code>']]),
  ('try', 'print(type(5))\nprint(type(5.0))\nprint(type("5"))\nprint(type(input()))', ['42'], 'type() tells you the type. Notice what input() gives, even for 42!'),
  ('rule', 'What happens when types mix? (memorise this)', '<b>int ± int = int</b> &nbsp;|&nbsp; <b>any float in the math = float</b> &nbsp;|&nbsp; <b>/ always = float</b> &nbsp;|&nbsp; <b>str + str = str (glued)</b> &nbsp;|&nbsp; <b>str * int = str (repeated)</b> &nbsp;|&nbsp; <b>str + int = ERROR</b> &nbsp;|&nbsp; <b>str * str = ERROR</b>'),
  ('h', 'The what-will-it-be table'),
  ('table', ['Expression', 'Type', 'Value'], [['<code>5 + 5</code>', 'int', '10'], ['<code>5 + 5.0</code>', 'float', '10.0'], ['<code>5 / 5</code>', 'float', '1.0'], ['<code>"5" + "5"</code>', 'str', '55'],
      ['<code>"5" * 3</code>', 'str', '555'], ['<code>"5" + 5</code>', '💥 TypeError', ''], ['<code>int("5") + 5</code>', 'int', '10']]),
  ('h', 'The four error names'),
  ('table', ['Error', 'It means', 'Example'], [
      ['<b>SyntaxError</b>', 'Python cannot even READ it: missing quote, bracket or comma', '<code>print("hi)</code>'],
      ['<b>NameError</b>', 'Python does not know that name: typo, capital letter, missing quotes, or variable never created', '<code>print(Hello)</code>'],
      ['<b>TypeError</b>', 'wrong TYPES mixed together', '<code>"5" + 5</code>'],
      ['<b>ValueError</b>', 'right type but the VALUE cannot be converted', '<code>int("abc")</code>'],
      ['<b>ZeroDivisionError</b>', 'divided by zero', '<code>5 / 0</code>']]),
  ('rule', 'How to read an error', '1) Look at the <b>line number</b>. 2) Read the <b>error name</b> (the first word). 3) Read the last sentence - it says what Python did not like.'),
  ('try', 'x = 3\ny = "4"\nprint(x + y)', [], 'Run it. Which error? Then fix it by changing y.'),
  ('quick', 'Which crashes?', ['"7" + 3', '7 + 3', '"7" + "3"', '"7" * 3'], 0, 'Only text + number.'),
  ('quick', 'What type is 10 / 5 ?', ['float', 'int', 'str', 'error'], 0, '/ = float, always.'),
  ('quick', 'int("hello") gives ...', ['ValueError', 'TypeError', 'NameError', 'SyntaxError'], 0, 'The text is not a number-looking text.'),
  ])

L(6, 'Whole programs: the 4-step recipe', '🧩', 30,
  'Build complete programs: INPUT, CONVERT, CALCULATE, PRINT.',
  ['I follow Ask - Convert - Calculate - Print', 'I choose int or float correctly', 'I print the right format with commas or +', 'I check my program with 2 test inputs in my head'],
  [
  ('p', 'Almost every test program follows the same recipe:'),
  ('pipeline', ['1. ASK', 'input()', 'get the text'], ['2. CONVERT', 'int() / float()', 'make it a number'], ['3. CALCULATE', '+ - * /', 'do the math'], ['4. PRINT', 'print()', 'show the answer']),
  ('p', 'Example: ask for a width and a height and print the area.'),
  ('try', 'w = int(input("Width: "))\nh = int(input("Height: "))\narea = w * h\nprint("Area:", area)', ['3', '4'], 'Step through to see each box fill up.'),
  ('rule', 'Before you write, answer 3 questions', '1) <b>What does the user type?</b> Whole number -> <code>int</code>. Decimal possible -> <code>float</code>.<br>2) <b>What is the formula?</b><br>3) <b>What exactly must be printed?</b> Look at the example output - spaces and capital letters must match.'),
  ('h', 'Worked example: temperature'),
  ('p', '<b>Task:</b> ask for a Celsius temperature and print Fahrenheit. Formula: <code>F = C * 9 / 5 + 32</code>'),
  ('show', 'c = float(input("Celsius: "))\nf = c * 9 / 5 + 32\nprint(f)', ['100']),
  ('p', 'Temperatures can have decimals, so <code>float</code>. The answer prints as <code>212.0</code> because a float always shows its decimal point.'),
  ('h', 'Worked example: mixing text and numbers'),
  ('show', 'name = input("Name: ")\nage = int(input("Age: "))\nprint(name, "will be", age + 1, "next year")', ['Ana', '10']),
  ('trap', 'To mix a number into text with <code>+</code> you would need str(). With <b>commas</b> you do not! That is why <code>print("Total:", total)</code> is the safe, easy choice.'),
  ('h', 'Debug checklist (use it on every wrong answer)'),
  ('list', ['Are my quotes and brackets in pairs?', 'Did I use <code>int()</code>/<code>float()</code> on every <code>input()</code> I do math with?', 'Is it int or float? (decimals? then float)', 'Do the capital letters and spaces in my print match the example EXACTLY?', 'Did I use the same variable name everywhere (spelling, capitals)?', 'Try it with the example input. Does the output match?']),
  ('quick', 'Ask for two numbers and print the SUM. Which is correct?', ['a = int(input())\nb = int(input())\nprint(a + b)', 'a = input()\nb = input()\nprint(a + b)', 'print(input() + input())', 'a = int(input)\nprint(a + a)'], 0, 'Convert both before adding.'),
  ])

L(7, 'Text tools: str(), f-strings, round()', '🎁', 25,
  'Print numbers inside sentences, control decimals, and use the other math operators.',
  ['I can use str() to join a number to text with +', 'I can write an f-string with {}', 'I can show 2 decimals with :.2f', 'I know what // and % do'],
  [
  ('p', 'On the test you mixed text and numbers with <b>commas</b>. Python has more tools that make output look professional. They are not on the test, but they make your programs much nicer.'),
  ('h', 'str(): turn a number into text'),
  ('rule', 'str() makes text from anything', '<code>str(5)</code> is the text <code>"5"</code>. Now you can glue it with <code>+</code> - no TypeError.'),
  ('show', 'age = 11\nprint("Age: " + str(age))\nprint(str(5) + str(5))\nprint(len(str(12345)))', []),
  ('try', 'age = int(input("Age? "))\nprint("In 5 years you will be " + str(age + 5) + ".")', ['11'], 'Run it. Then delete <code>str( )</code> and run again to see the TypeError from lesson 5.'),
  ('trap', 'You must convert BEFORE gluing: <code>"Age: " + age</code> crashes when age is a number. And <code>str(5) + str(5)</code> is <code>"55"</code>, not 10.'),
  ('h', 'f-strings: put values inside a sentence'),
  ('rule', 'Put an f before the quote, values go in { }', 'Inside the curly brackets you can put a variable <b>or even math</b>. No str() needed.'),
  ('show', 'name = "Ana"\nage = 11\nprint(f"{name} is {age} years old")\nprint(f"Next year: {age + 1}")', []),
  ('try', 'item = "pizza"\nprice = 4\nqty = 3\nprint(f"{qty} {item} cost {price * qty} dollars")', [], 'Change the numbers and the item, then run again.'),
  ('trap', 'Forget the <code>f</code> and Python prints the curly brackets as plain text:'),
  ('show', 'x = 7\nprint("x is {x}")\nprint(f"x is {x}")', []),
  ('h', 'Decimals: :.2f'),
  ('p', 'Money needs exactly two decimals. After the value inside the brackets write <code>:.2f</code> ("2 digits after the point, as a float").'),
  ('show', 'price = 2.5\nprint(price)\nprint(f"${price:.2f}")\nx = 3.14159\nprint(f"{x:.2f} {x:.1f} {x:.0f}")', []),
  ('try', 'total = float(input("Total: "))\npeople = int(input("People: "))\nprint(f"Each pays ${total / people:.2f}")', ['10', '4'], 'Try 10 and 3 too. The cents always show.'),
  ('h', 'round(), and the other operators'),
  ('table', ['Tool', 'Example', 'Result', 'Remember'], [['<code>round(x)</code>', '<code>round(3.7)</code>', '4', 'rounds to the nearest whole number (int() would chop to 3)'], ['<code>round(x, 1)</code>', '<code>round(2.567, 1)</code>', '2.6', 'keeps 1 decimal'],
     ['<code>//</code>', '<code>17 // 5</code>', '3', 'how many times it fits (whole-number divide)'], ['<code>%</code>', '<code>17 % 5</code>', '2', 'the remainder'], ['<code>**</code>', '<code>2 ** 5</code>', '32', 'power: 2 times itself 5 times']]),
  ('show', 'print(round(3.7), int(3.7))\nprint(round(2.5), round(3.5))\nprint(47 // 10, 47 % 10)\nprint(2 ** 10)', []),
  ('trap', '<code>round(2.5)</code> is <b>2</b> and <code>round(3.5)</code> is <b>4</b>. When the digit is exactly .5, Python rounds to the nearest EVEN number. Do not be surprised!'),
  ('rule', 'Handy uses of // and %', '<code>n % 2 == 0</code> means n is even. <code>n // 10</code> and <code>n % 10</code> split a 2-digit number into its tens and ones. <code>minutes // 60</code> and <code>minutes % 60</code> turn minutes into hours and minutes.'),
  ('try', 'minutes = int(input("Minutes: "))\nprint(minutes // 60, "hours and", minutes % 60, "minutes")', ['135'], 'Try 60, 59 and 200.'),
  ('quick', 'What does print(f"{2 + 3} and {2 * 3}") show?', ['5 and 6', '2 + 3 and 2 * 3', '23 and 23', 'Error'], 0, 'Inside the curly brackets Python does the math: 5 and 6.'),
  ('quick', 'What does print(17 % 5) show?', ['2', '3', '3.4', '85'], 0, '17 = 3 * 5 + 2. The remainder is 2.'),
  ('quick', 'Which prints 4.50 from price = 4.5 ?', ['print(f"{price:.2f}")', 'print(round(price, 2))', 'print(price)', 'print(str(price) + "0")'], 0, ':.2f always shows two decimals. round(4.5, 2) prints 4.5.'),
  ])
